import unittest
from candidate import separate_paren_groups

class TestSeparateParenGroups(unittest.TestCase):
    def test_normal_single_group(self):
        self.assertEqual(separate_paren_groups('()'), ['()'])

    def test_normal_multiple_groups(self):
        self.assertEqual(separate_paren_groups('(())()((()))'), ['(())', '()', '((()))'])

    def test_ignore_spaces_between_groups(self):
        self.assertEqual(separate_paren_groups('( ) (( )) (( )( ))'), ['()', '(())', '(()())'])

    def test_ignore_whitespace_inside_groups(self):
        self.assertEqual(separate_paren_groups(' ( ( ) ( ) ) '), ['(()())'])

    def test_empty_string(self):
        self.assertEqual(separate_paren_groups(''), [])

    def test_string_with_only_spaces(self):
        self.assertEqual(separate_paren_groups('   \t\n  '), [])

    def test_unmatched_open_parentheses(self):
        self.assertEqual(separate_paren_groups('((('), [])

    def test_unmatched_close_parentheses(self):
        self.assertEqual(separate_paren_groups(')))'), [])

    def test_mixed_unmatched_parentheses(self):
        self.assertEqual(separate_paren_groups(')()('), [')('])

    def test_nested_parentheses_only(self):
        self.assertEqual(separate_paren_groups('((()))'), ['((()))'])

    def test_complex_nested_groups(self):
        self.assertEqual(separate_paren_groups('(())((())((()))())'), ['(())', '((())((()))())'])

    def test_non_string_input_type_error(self):
        with self.assertRaises(TypeError):
            separate_paren_groups(123)

    def test_none_input_type_error(self):
        with self.assertRaises(TypeError):
            separate_paren_groups(None)

    def test_result_is_list_of_strings(self):
        result = separate_paren_groups('(())()')
        self.assertIsInstance(result, list)
        for item in result:
            self.assertIsInstance(item, str)

    def test_multiple_consecutive_groups(self):
        self.assertEqual(separate_paren_groups('()()()'), ['()', '()', '()'])

    def test_group_with_internal_spaces(self):
        self.assertEqual(separate_paren_groups(' ( ( ) ) ( ( ) ) '), ['(())', '(())'])

    def test_group_with_newlines_and_tabs(self):
        self.assertEqual(separate_paren_groups('(\n())\t()'), ['(())', '()'])

    def test_no_groups_due_to_incomplete_parentheses(self):
        self.assertEqual(separate_paren_groups('(()'), [])

    def test_large_input_with_many_groups(self):
        input_str = '()()()()()()()()()()'
        expected = ['()'] * 10
        self.assertEqual(separate_paren_groups(input_str), expected)

    def test_input_with_non_parentheses_characters(self):
        self.assertEqual(separate_paren_groups('(a)(b)(c)'), ['()', '()', '()'])

    def test_input_with_nested_and_non_parentheses(self):
        self.assertEqual(separate_paren_groups('(a(b)c)'), ['()'])

if __name__ == '__main__':
    unittest.main()
